Given an integer n, generate all n-bit Gray codes. A Gray code sequence starts with n zeros, and every consecutive code in the sequence differs from the previous one by exactly one bit.Examples:Input: n = 2Output: ["00", "01", "11", "10"]Explanation: The sequence starts with 00. Every consecutive pair of codes differs by exactly one bit.Input: n = 3Output: ["000", "001", "011", "010", "110", "111", "101", "100"]Explanation: The sequence starts with 000, and every consecutive pair of codes differs by exactly one bit.Try It YourselfTable of ContentUsing Reflection Method - O(n*(2^n)) Time and O(n*(2^n)) SpaceUsing Bit Manipulation -  O(n*(2^n)) Time and O(n*(2^n)) SpaceUsing Reflection Method - O(n*(2^n)) Time and O(n*(2^n)) SpaceThe idea is based on the fact that an n-bit Gray code sequence can be generated from an (n - 1)-bit Gray code sequence. We start with the 1-bit Gray code sequence {"0", "1"}.For each new bit position, we first copy the current Gray code sequence in reverse order and append it to the original sequence. Then, we prefix 0 to all codes in the first half and prefix 1 to all codes in the second half. The resulting sequence forms the Gray codes of the next length.To generate 3-bit Gray codes from 2-bit Gray codes:The 2-bit Gray code sequence is: 00 01 11 10Copy the sequence in reverse order: 10 11 01 00Add prefix 0 to the original sequence: 000 001 011 010Add prefix 1 to the reversed sequence: 110 111 101 100Combining both sequences gives 3- bit Gray codes: 000 001 011 010 110 111 101 100
            C++

    #include <iostream>
#include <vector>
#include <string>
using namespace std;

vector<string> generateGrayCodes(int n) {
    vector<string> res;

    // base case
    res.push_back("0");
    res.push_back("1");

    for (int i = 2; i <= n; i++) {
        int size = res.size();

        // reverse and append
        for (int j = size - 1; j >= 0; j--) {
            res.push_back(res[j]);
        }

        // add '0' to first half
        for (int j = 0; j < size; j++) {
            res[j] = "0" + res[j];
        }

        // add '1' to second half
        for (int j = size; j < 2 * size; j++) {
            res[j] = "1" + res[j];
        }
    }

    return res;
}

int main() {
    int n = 3;
    vector<string> res = generateGrayCodes(n);

    cout << "[";
        for (int i = 0; i < res.size(); i++) {
            cout << res[i];
            if (i < res.size() - 1)
                cout << ", ";
        }
        cout << "]\n";
    return 0;
}


            Java

    import java.util.ArrayList;

class GFG {
    public static ArrayList<String> generateGrayCodes(int n) {
        ArrayList<String> res = new ArrayList<>();

        res.add("0");
        res.add("1");

        for (int i = 2; i <= n; i++) {
            int size = res.size();

            // reverse and append
            for (int j = size - 1; j >= 0; j--) {
                res.add(res.get(j));
            }

            // prefix '0'
            for (int j = 0; j < size; j++) {
                res.set(j, "0" + res.get(j));
            }

            // prefix '1'
            for (int j = size; j < 2 * size; j++) {
                res.set(j, "1" + res.get(j));
            }
        }

        return res;
    }

    public static void main(String[] args) {
        int n = 3;
        ArrayList<String> res = generateGrayCodes(n);

        System.out.print(res);
    }
}


