    #include <iostream>
#include <vector>
#include <string>
using namespace std;

vector<string> generateGrayCodes(int n) {
    vector<string> res;

    for (int i = 0; i < (1 << n); i++) {

        // generate i-th Gray code
        int g = i ^ (i >> 1);

        // Convert the code to string
        string s = "";
        for (int j = n - 1; j >= 0; j--) {
            if (g & (1 << j))
                s += '1';
            else
                s += '0';
        }

        res.push_back(s);
    }

    return res;
}

int main() {
    int n = 3;
    vector<string> res = generateGrayCodes(n);
